INSERT INTO focus_session(
    user_id, started_at, duration_minutes, mode, label, idempotency_key, version, created_at, updated_at
)
VALUES(
    #{userId}, #{startedAt}, #{durationMinutes}, #{mode}, #{label}, #{idempotencyKey}, #{version}, #{createdAt}, #{updatedAt}
)
ON DUPLICATE KEY UPDATE id = LAST_INSERT_ID(id)

mapper.select:
SELECT id, started_at, duration_minutes, mode, label, created_at
FROM focus_session
WHERE user_id = #{userId} AND id = #{id}

SELECT id, started_at, duration_minutes, mode, label, created_at
FROM focus_session
WHERE user_id = #{userId} AND idempotency_key = #{idempotencyKey}

SELECT id, started_at, duration_minutes, mode, label, created_at
FROM focus_session
WHERE user_id = #{userId}
ORDER BY started_at DESC, id DESC
LIMIT #{limit} OFFSET #{offset}
